    for(const action of [()=>provider?.close(),()=>close(merchantServer),()=>close(nativeServer),()=>authority.close()])
      try{await action();}catch(error){errors.push(String(error));}
    if(errors.length){if(primary)primary.closeErrors=errors;else throw new Error('Upload fixture close failed: '+errors.join('; '));}
    if(report.merchantUpload)report.merchantUpload.closed=true;
  }
}
